// Normalize the crash payload (Crashlytics/Sentry/Bugsnag shapes vary) into a
// consistent list of frames, then pick the top app-owned candidate frame(s).
const cfg = $input.first().json;
const crash = cfg.body || cfg;

const prefixes = (cfg.appOwnedPathPrefixes || '').split(',').map(s => s.trim()).filter(Boolean);
const maxCandidates = cfg.maxCandidateFrames || 2;

// Accept either a flat stackTrace array (Crashlytics-ish) or nested
// exception.stacktrace.frames (Sentry-ish) - normalize both.
let rawFrames = crash.stackTrace
  || crash.exception?.stacktrace?.frames
  || crash.exceptions?.[0]?.stacktrace?.frames
  || [];

const frames = rawFrames.map(f => ({
  file: f.file || f.filename || f.fileName || '',
  function: f.function || f.functionName || f.method || '',
  line: f.line || f.lineNumber || f.line_number || null
})).filter(f => f.file);

function isAppOwned(filePath) {
  if (!prefixes.length) return true;
  return prefixes.some(p => filePath.startsWith(p));
}

const appFrames = frames.filter(f => isAppOwned(f.file));
const candidateFrames = (appFrames.length ? appFrames : frames).slice(0, maxCandidates);

return [{
  json: {
    ...cfg,
    platform: crash.platform || 'unknown',
    appVersion: crash.appVersion || crash.appVersionCode || 'unknown',
    crashTimestamp: crash.crashTimestamp || crash.timestamp || new Date().toISOString(),
    exceptionType: crash.exceptionType || crash.exception?.type || 'UnknownException',
    exceptionMessage: crash.exceptionMessage || crash.exception?.value || '',
    affectedUsersCount: crash.affectedUsersCount || crash.usersAffected || null,
    crashFreeSessionPct: crash.crashFreeSessionPct ?? null,
    fullStackTrace: frames,
    candidateFrames
  }
}];

// Collect commit history + blame evidence per candidate frame into one
// item per crash, ready for the Claude correlation prompt.
const items = $input.all();
const base = $('JS - Parse Stack Trace & Extract Frames').first().json;

const evidenceByFrame = items.map((item, idx) => {
  const all = item.json;
  const commits = all.commits || all[0] || [];
  const fileContent = all.content || all[1] || {};
  const frame = all.candidateFrames || base.candidateFrames[idx] || {};

  const commitSummaries = (Array.isArray(commits) ? commits : []).slice(0, 10).map(c => ({
    sha: c.sha,
    author: c.commit?.author?.name || c.author?.login || 'unknown',
    date: c.commit?.author?.date,
    message: (c.commit?.message || '').split('\n')[0],
    url: c.html_url
  }));

  return {
    file: frame.file,
    function: frame.function,
    line: frame.line,
    recentCommits: commitSummaries,
    lastKnownAuthor: fileContent.author || (commitSummaries[0] && commitSummaries[0].author) || 'unknown'
  };
});

return [{ json: { ...base, evidenceByFrame } }];

const cfg = $('JS - Aggregate Candidate Frame Evidence').first().json;
const response = $input.first().json;

const textBlock = (response.content || []).find(b => b.type === 'text');
let parsed = {};
try {
  const raw = (textBlock?.text || '{}').replace(/```json|```/g, '').trim();
  parsed = JSON.parse(raw);
} catch (e) {
  parsed = { parseError: true, confidencePercent: 0, mostLikelyResponsible: { file: cfg.candidateFrames?.[0]?.file || 'unknown', author: 'unknown', commitSha: null, commitMessage: null, commitUrl: null }, reasoning: 'Could not parse model response.', likelyBugExplanation: '', suggestedFixDirection: '', alternativeSuspects: [] };
}

return [{
  json: {
    repoOwner: cfg.repoOwner,
    repoName: cfg.repoName,
    taskProviderBaseUrl: cfg.taskProviderBaseUrl,
    slackChannelId: cfg.slackChannelId,
    minConfidenceForAutoAssign: cfg.minConfidenceForAutoAssign,
    platform: cfg.platform,
    appVersion: cfg.appVersion,
    exceptionType: cfg.exceptionType,
    exceptionMessage: cfg.exceptionMessage,
    affectedUsersCount: cfg.affectedUsersCount,
    crashFreeSessionPct: cfg.crashFreeSessionPct,
    fullStackTrace: cfg.fullStackTrace,
    ...parsed
  }
}];

